/* Review questions and AP exam links, merged into each tool by BioLab.addReview. "verify" is read only by the test script. */
BioLab.addReview({
hardyweinberg:{
  apNote:'The Hardy–Weinberg equations are on the formula sheet. The released free-response sets checked for this tool (2019, 2023, 2025 and 2026) don’t ask for a Hardy–Weinberg calculation, so these links are the closest related questions.',
  ap:[
    {title:'AP Biology equations and formulas sheet',url:'https://apcentral.collegeboard.org/media/pdf/ap-biology-equations-and-formulas-sheet.pdf',note:'Has p² + 2pq + q² = 1 and p + q = 1, plus chi-square critical values.'},
    {title:'2026 AP Biology free-response, Question 5',url:'https://apcentral.collegeboard.org/media/pdf/ap26-frq-biology.pdf',note:'Natural selection on a heritable trait in anole lizards.'},
    {title:'2025 AP Biology free-response, Question 4',url:'https://apcentral.collegeboard.org/media/pdf/ap25-frq-biology.pdf',note:'Genetic evidence that a population is evolving, and how isolation leads to divergence.'},
    {title:'All released AP Biology exam questions',url:'https://apcentral.collegeboard.org/courses/ap-biology/exam/past-exam-questions',note:'Free-response questions by year, with scoring guidelines.'}
  ],
  questions:[
  {id:'carrier',kind:'real',lvl:'bio',
    q:'A recessive genetic condition affects about 1 in 2,500 newborns in a population at Hardy–Weinberg equilibrium. About how many people are carriers, with one copy and no condition?',
    choices:['About 1 in 25','About 1 in 50','About 1 in 1,250','About 1 in 2,500'],correct:0,
    steps:['Affected people are aa, so q² = 1 ÷ 2,500 = 0.0004. That makes q = 0.02.','Then p = 1 − q = 0.98, and carriers are 2pq = 2 × 0.98 × 0.02 = 0.039, which is about 1 in 25.','Carriers are far more common than people with the condition. That’s why genetic counselors care about this math.'],
    lab:{set:{p:.98},look:'p is set to 0.98. Compare <b>Expected Aa</b> with <b>Expected aa</b>. The aa number is so small that it rounds to 0%.'},verify:[['Aa',3.92,.05],['aa',.04,.01]]},
  {id:'white',kind:'test',lvl:'bio',
    q:'In a population at equilibrium, 16% of the plants are white (aa). What percent are heterozygous (Aa)?',
    num:{ans:48,tol:.5,unit:'%'},
    steps:['White plants are q², so q² = 0.16 and q = 0.4. The common mistake is to use 0.16 as q.','p = 1 − 0.4 = 0.6.','Aa = 2pq = 2 × 0.6 × 0.4 = 0.48, or 48%.'],
    lab:{set:{p:.6},look:'p is set to 0.6. Read <b>Expected AA</b>, <b>Expected Aa</b> and <b>Expected aa</b>. They add up to 100%.'},verify:[['Aa',48,.01],['aa',16,.01],['AA',36,.01]]},
  {id:'count',kind:'test',lvl:'bio',
    q:'Purple (A) is dominant over white (a). You want to find the allele frequencies. Why start from the white plants?',
    choices:['White plants are more common than purple plants.','White plants show their genotype (aa). Purple plants could be AA or Aa, and they look the same.','The white allele is always the rarer one.','The purple plants don’t follow Hardy–Weinberg.'],correct:1,
    steps:['Every white plant must be aa, so counting them gives q² directly.','Purple plants mix two genotypes you can’t tell apart by looking, so their count doesn’t give p².','From q² you can get q, then p, then every other genotype.'],
    lab:{set:{p:.7},look:'Look at the plants on screen. Purple ones can be AA or Aa, and only white ones show their genotype.'}},
  {id:'dominant',kind:'test',lvl:'honors',
    q:'A dominant allele starts at p = 0.2 in a large population that meets all the Hardy–Weinberg conditions. What happens to p over 10 generations?',
    choices:['It rises, because dominant alleles take over.','It falls, because rare alleles get lost.','It stays at 0.2.','It rises to 0.75, the 3:1 ratio.'],correct:2,
    steps:['Dominant describes how an allele shows up in a plant. It says nothing about whether the allele spreads.','With no selection, mutation, migration, drift or non-random mating, allele frequencies don’t change.','The 3:1 ratio comes from one Aa × Aa cross, not from a whole population.'],
    lab:{set:{p:.2},act:'gen10',look:'Ten generations run with every condition met. Watch <b>Allele A (p)</b> stay put.'},verify:[['pA',.2,.015]],wait:4.2},
  {id:'hidden',kind:'real',lvl:'honors',
    q:'Selection works against white (aa) plants, which survive half as well. Starting from q = 0.3, what happens to the white allele after 10 generations in this model?',
    choices:['It’s gone within a few generations.','It falls, but doesn’t disappear, because Aa plants carry it where selection can’t see it.','It stays at 0.3.','It rises, because white plants need more copies.'],correct:1,
    steps:['Selection acts on what it can see. It only removes a alleles when they’re in aa plants.','As q falls, aa plants get rarer (q²), so most remaining a alleles are hidden in Aa plants (2pq) and selection slows down.','This is why harmful recessive alleles stay in real populations for a very long time.'],
    lab:{set:{p:.7,nosel:false},act:'gen10',look:'Selection is on and ten generations run. Watch <b>Allele a (q)</b> fall, then slow down.'},verify:[['qa',.17,.06]],wait:4.2},
  {id:'drift',kind:'real',lvl:'honors',
    q:'A conservation team moves 20 plants from a large population to a new site. Nothing is selecting for or against either allele. What should they expect?',
    choices:['Allele frequencies will match the original population.','Allele frequencies will wander by chance, and an allele could be lost.','The dominant allele will always win.','New mutations will quickly make up for the small size.'],correct:1,
    steps:['Each generation is a sample of the last one. In a small sample, chance matters a lot. That’s genetic drift.','Run it again and you’ll get a different path, because no direction is favored.','Once an allele is lost, only mutation or migration brings it back. That’s why small populations lose genetic variety.'],
    lab:{set:{p:.5,large:false},act:'gen10',look:'Only 20 plants. Watch <b>Allele A (p)</b>, then press <b>Start over</b> and run it again. The path changes.'}},
  {id:'chi',kind:'ap',lvl:'ap',
    q:'A sample of 100 plants has 60 AA, 20 Aa and 20 aa. From these counts p = 0.7, so the expected counts are 49, 42 and 9. Calculate χ².',
    num:{ans:27.4,tol:.4,unit:''},
    steps:['χ² = Σ(o − e)² ÷ e = (60 − 49)² ÷ 49 + (20 − 42)² ÷ 42 + (20 − 9)² ÷ 9.','= 2.47 + 11.52 + 13.44 = 27.4.','That’s far above the cutoff at p = 0.05, whether your class uses 3.84 (df = 1, since p came from the same data) or 5.99 (df = 2). Reject the idea that this population is at equilibrium.'],
    lab:{set:{p:.7,random:false},act:'gen1',look:'Inbreeding is on, which gives a similar shortage of Aa plants. Read the <b>χ²</b> tile and compare it with the cutoff.'},wait:.8,verifyAbove:['chi',3.84]},
  {id:'inbreed',kind:'ap',lvl:'ap',
    q:'Over 10 generations, a population’s allele frequencies stay the same, but it has fewer heterozygotes than 2pq predicts. Which condition is most likely being broken?',
    choices:['No natural selection','No mutation','Random mating','No migration'],correct:2,
    steps:['Non-random mating, like inbreeding, shuffles alleles into different genotypes. It makes more homozygotes and fewer heterozygotes.','It doesn’t add or remove alleles, so p and q stay put.','Selection, mutation and migration all change allele frequencies, which doesn’t match this data. So a stable p doesn’t prove that a population is at equilibrium.'],
    lab:{set:{p:.7,random:false},act:'gen10',look:'Inbreeding is on. Watch <b>Allele A (p)</b> hold steady while the Aa count stays under the expected number.'},verify:[['pA',.7,.02]],wait:4.2}
  ]},
waterprops:{
  apNote:'Water’s properties come up across the AP Biology exam, usually inside a bigger question. Ask your teacher which released questions fit this unit.',
  ap:[{title:'All released AP Biology exam questions',url:'https://apcentral.collegeboard.org/courses/ap-biology/exam/past-exam-questions',note:'Free-response questions by year, with scoring guidelines.'}],
  questions:[
  {id:'polar',kind:'test',lvl:'bio',
    q:'In a water molecule, the oxygen atom pulls the shared electrons closer to itself than the hydrogen atoms do. What does that make water?',
    choices:['Polar: the oxygen end is slightly negative and the hydrogen ends are slightly positive','Nonpolar: the charges cancel out','An ion with a full negative charge','Hydrophobic: it avoids other molecules'],correct:0,
    steps:['Oxygen holds the shared electrons more tightly than hydrogen does.','So the oxygen end carries a small negative charge (δ−) and each hydrogen end a small positive charge (δ+).','A molecule with uneven charge like this is polar. Polarity is why water sticks to itself, sticks to other polar things and dissolves salts.'],
    lab:{set:{station:'7'},act:'rub',look:'The balloon is charged. Press <b>Bring the balloon close</b> and watch the stream of water bend toward it. Charge on the balloon pulls on the water’s charges; switch the stream to oil and compare.'}},
  {id:'hbond',kind:'test',lvl:'bio',
    q:'What is a hydrogen bond in water?',
    choices:['The bond between the O and an H inside one water molecule','A weak attraction between the δ+ hydrogen of one molecule and the δ− oxygen of a neighbor','The bond holding two hydrogen atoms together as H₂','A bond that only forms when water freezes'],correct:1,
    steps:['Inside one water molecule, O and H share electrons. That is a covalent bond, and it is strong.','A hydrogen bond is between molecules: the slightly positive H of one molecule is attracted to the slightly negative O of the next.','Hydrogen bonds are weak one at a time, but water has so many of them that they cause cohesion, surface tension and high specific heat. They form in liquid water too, not only in ice.'],
    lab:{set:{station:'2',mol:true},act:'drop',look:'Keep adding drops and watch the molecule zoom. The dashed lines between molecules are hydrogen bonds.'}},
  {id:'sweat',kind:'real',lvl:'bio',
    q:'On a hot run, sweat evaporating from your skin cools you down. Which property of water explains why so much heat leaves with the sweat?',
    choices:['Its high heat of vaporization: hydrogen bonds must break before a molecule can escape as vapor','Its low density','Its surface tension','It is a base'],correct:0,
    steps:['To leave as vapor, a water molecule has to break all its hydrogen bonds to its neighbors.','Breaking them takes energy, and that energy comes from your skin as heat.','Each gram of sweat that evaporates carries away more than 2,000 J. That is why sweating works, and why humid days, when sweat can’t evaporate, feel so much hotter.'],
    lab:{set:{station:'5'},act:'heat',look:'Water, alcohol and oil get the same heat. Water needs the most energy to warm up and boil, because of its hydrogen bonds.'}},
  {id:'dissolve',kind:'test',lvl:'honors',
    q:'You stir salt, sugar and cooking oil into three beakers of water. Which ones dissolve?',
    choices:['All three','Salt and sugar, but not oil','Only salt, because it is made of ions','Only the oil'],correct:1,
    steps:['Water dissolves things that are charged (ions, like Na⁺ and Cl⁻ from salt) or polar (like sugar). Its δ+ and δ− ends surround each particle and pull it away from the rest.','Oil is nonpolar. Water molecules are more attracted to each other than to oil, so the oil stays in its own layer.','This is “like dissolves like,” and it is why your blood can carry sugar and salts but carries fats inside protein packages.'],
    lab:{set:{station:'6'},act:'salt',look:'Salt is in. Press <b>Stir</b>, then add sugar and oil and stir again. Read <b>Dissolved?</b> each time.'}},
  {id:'ice',kind:'real',lvl:'honors',
    q:'Fish survive a Colorado winter under a frozen reservoir. Why does the lake freeze from the top down instead of from the bottom up?',
    choices:['Ice is less dense than liquid water, so it floats and insulates the water below','Cold water rises because it is lighter','The bottom is warmed by the fish','Ice is denser, so it sinks and the lake fills with ice from the bottom'],correct:0,
    steps:['As water freezes, hydrogen bonds lock the molecules into an open hexagon pattern with space in the middle.','That makes ice less dense than liquid water (about 0.92 vs 1.00 g/mL), so it floats.','The floating ice insulates the liquid water underneath, so the lake does not freeze solid.'],
    lab:{set:{station:'1'},act:'winter',look:'Watch the lake freeze. Ice forms on top and the water under it stays liquid.'}}
  ]},
water:{
  questions:[
  {id:'mass',kind:'test',lvl:'bio',
    q:'Two beakers of water start at 20 °C on identical 150 W hot plates. One holds 100 g and the other 200 g. After 1 minute, which is hotter?',
    choices:['The 100 g beaker: it warms about twice as much','The 200 g beaker, because it holds more heat','They are the same temperature'],correct:0,
    steps:['Both get the same energy: 150 W × 60 s = 9,000 J.','Temperature rise = energy ÷ (mass × 4.18 J/g·°C). For 100 g that is 21.5 °C, so it reaches 41.5 °C.','For 200 g it is 10.8 °C, so it only reaches 30.8 °C. Twice the water takes twice the energy for the same rise.'],
    lab:{set:{mass:200},act:'warm',look:'This is the 200 g beaker. Pause at exactly 1:00 and read the <b>Temperature</b>. Then set the mass to 100 g and compare.'},verify:[['temp',30.8,.1],['energy',9,.01]],wait:1},
  {id:'plateau',kind:'test',lvl:'bio',
    q:'A thermometer in melting ice reads 0 °C for several minutes even though the hot plate is on. Where is the heat going?',
    choices:['Into breaking hydrogen bonds so the ice can melt','Nowhere: the hot plate must be broken','Into making the ice colder','Only into the air'],correct:0,
    steps:['While ice melts, the heat breaks the hydrogen bonds that hold the ice lattice together.','None of it goes into making the molecules move faster, so the temperature stays at 0 °C.','Once all the ice has melted, the temperature starts to climb again.'],
    lab:{set:{power:300},act:'cold',look:'The ice starts at −20 °C with a 300 W heater. Watch the <b>Temperature</b> stop at 0 °C while the <b>State</b> says Melting.'},verify:[['temp',0,.01]],wait:2},
  {id:'q',kind:'test',lvl:'honors',
    q:'How much energy does it take to warm 250 g of water from 20 °C to 80 °C? Water’s specific heat is 4.18 J/g·°C. Give your answer in kJ.',
    num:{ans:62.7,tol:.5,unit:'kJ'},
    steps:['Use Q = m × c × ΔT.','Q = 250 g × 4.18 J/g·°C × (80 − 20) °C = 62,700 J.','That is 62.7 kJ. At 150 W it takes 62,700 ÷ 150 = 418 s, just under 7 minutes.'],
    lab:{set:{mass:250},act:'warm',look:'250 g starting at 20 °C. The run stops at 80 °C so you can read <b>Energy added</b>.'},verify:[['temp',80,.1],['energy',62.7,.1]],wait:6.9667},
  {id:'coast',kind:'real',lvl:'honors',
    q:'San Diego’s temperature swings much less between day and night than the desert inland does. Which property of water explains the difference?',
    choices:['Water’s high specific heat: the ocean soaks up and releases huge amounts of heat with little temperature change','Water’s low boiling point','Ice floats','Water is a good solvent'],correct:0,
    steps:['Water needs 4.18 J to warm 1 g by 1 °C, about 1.7 times as much as ethanol and more than twice as much as oil, because heat goes into hydrogen bonds first.','The Pacific absorbs heat during the day and releases it at night without changing temperature much, and the coastal air follows.','Dry desert sand and air have little water, so they heat and cool fast.'],
    lab:{set:{sub:'ethanol'},act:'warm',look:'This is ethanol, with fewer hydrogen bonds. Watch how fast it warms, then switch Substance to Water and compare.'}},
  {id:'boil',kind:'ap',lvl:'ap',
    q:'A 500 W kettle holds 400 g of water already at 100 °C. How many minutes does it take to boil all of it away? The heat of vaporization is 2,260 J/g.',
    num:{ans:30.1,tol:.3,unit:'min'},
    steps:['Energy needed: Q = m × L = 400 g × 2,260 J/g = 904,000 J.','Time = energy ÷ power = 904,000 J ÷ 500 W = 1,808 s.','1,808 s ÷ 60 = 30.1 minutes, all at 100 °C. Boiling water away takes far more energy than heating it, because every hydrogen bond must break.']}
  ]},
macromolecules:{
  apNote:'Macromolecule structure shows up in AP Biology Unit 1 questions, often as “which monomer” or “which bond” parts of a free-response question.',
  ap:[{title:'All released AP Biology exam questions',url:'https://apcentral.collegeboard.org/courses/ap-biology/exam/past-exam-questions',note:'Free-response questions by year, with scoring guidelines.'}],
  questions:[
  {id:'monomers',kind:'test',lvl:'bio',
    q:'Starch, a protein and DNA are all polymers. Which list gives their monomers, in that order?',
    choices:['Glucose, amino acids, nucleotides','Amino acids, glucose, nucleotides','Glucose, nucleotides, amino acids','Fatty acids, amino acids, glucose'],correct:0,
    steps:['Starch is a carbohydrate, a chain of glucose.','Proteins are chains of amino acids, joined by peptide bonds.','DNA is a chain of nucleotides. Fatty acids are not monomers of a polymer: they join glycerol to make a fat.'],
    lab:{set:{mono:'amino'},look:'Read <b>What you are building</b>. Then switch the Monomer to Glucose, Nucleotide and Fatty acid and read it again.'}},
  {id:'waters',kind:'test',lvl:'bio',
    q:'25 glucose molecules join into one starch chain. How many water molecules are released?',
    num:{ans:24,tol:0,unit:'water molecules'},
    steps:['Each new bond between two glucose molecules releases one water. That is dehydration synthesis.','A chain of 25 units has 24 bonds between neighbors, like 25 paper-chain links with 24 joints.','So 24 waters are released. The common mistake is to answer 25.'],
    lab:{set:{start:12},act:'joinall',look:'12 glucose join into one chain. Read <b>Bonds in the chain</b> and <b>Water released</b>: both end at 11.'}},
  {id:'digest',kind:'real',lvl:'bio',
    q:'Chew a cracker for a minute and it starts to taste sweet, because an enzyme in your saliva breaks starch into sugars. What kind of reaction is that, and what does it use up?',
    choices:['Hydrolysis: it uses up one water molecule for every bond it breaks','Dehydration synthesis: it releases water','Hydrolysis: it releases one water for every bond','It needs no water at all'],correct:0,
    steps:['Breaking a bond between two monomers is the reverse of building it.','“Hydro-lysis” means splitting with water: a water molecule splits, giving –H to one sugar and –OH to the other.','So digestion uses water, one molecule per bond broken.'],
    lab:{set:{start:6,startAs:'chain'},act:'splitall',look:'A 6-glucose chain is split apart. Watch <b>Water used</b> climb to 5 as each bond breaks.'}},
  {id:'fat',kind:'test',lvl:'bio',
    q:'One glycerol joins three fatty acids to make a fat (a triglyceride). How many waters are released, and is the fat a polymer?',
    choices:['3 waters, and no: a fat is not a chain of repeating monomers','2 waters, and yes','3 waters, and yes: it is a polymer of fatty acids','1 water, and no'],correct:0,
    steps:['Glycerol has three –OH groups. Each one bonds to one fatty acid, and each bond releases one water. That makes 3.','A polymer is a long chain of repeating monomers that can keep growing. A fat stops at three fatty acids on one glycerol.','So lipids are built by dehydration synthesis too, but they are not polymers.'],
    lab:{set:{mono:'fat'},act:'joinall',look:'Three fatty acids join glycerol. Read <b>Water released</b> and <b>What you are building</b>.'}},
  {id:'notpoly',kind:'test',lvl:'honors',
    q:'Which of these is NOT a polymer?',
    choices:['Starch','A protein','DNA','A triglyceride (fat)'],correct:3,
    steps:['Starch, proteins and DNA are long chains of repeating monomers: glucose, amino acids and nucleotides.','A triglyceride is one glycerol with three fatty acids. It has no repeating chain and stops at three.','That is why biology books list lipids as macromolecules but not as polymers.'],
    lab:{set:{mono:'fat'},act:'joinall',look:'Watch the fat form, then try <b>Add a monomer</b>. Glycerol can’t take a fourth fatty acid.'}},
  {id:'pep',kind:'ap',lvl:'ap',
    q:'Four alanine molecules (89.09 g/mol each) join into a short polypeptide. What is its molar mass in g/mol? Water is 18.02 g/mol.',
    num:{ans:302.3,tol:.5,unit:'g/mol'},
    steps:['Four monomers make three peptide bonds, and each bond releases one water.','Mass = 4 × 89.09 − 3 × 18.02 = 356.36 − 54.06.','= 302.30 g/mol. Subtract n − 1 waters, not n.'],
    lab:{set:{mono:'amino',start:4},act:'joinall',look:'Four amino acids join. Read <b>Chain mass</b> when the chain is done.'}},
  {id:'tri',kind:'ap',lvl:'ap',
    q:'Glycerol (92.09 g/mol) joins three palmitic acid molecules (256.42 g/mol each). What is the molar mass of the fat? Water is 18.02 g/mol.',
    num:{ans:807.3,tol:.5,unit:'g/mol'},
    steps:['A fat has one bond per fatty acid, so three bonds release three waters.','Mass = 92.09 + 3 × 256.42 − 3 × 18.02 = 92.09 + 769.26 − 54.06.','= 807.29 g/mol, the molar mass of tripalmitin, a fat in palm oil.'],
    lab:{set:{mono:'fat'},act:'joinall',look:'Read <b>Chain mass</b> once all three fatty acids have joined.'}}
  ]},
foodtests:{
  questions:[
  {id:'iodine',kind:'test',lvl:'bio',
    q:'Which reagent tests for starch, and what does a positive result look like?',
    choices:['Iodine: it turns from amber to blue-black','Benedict’s: it turns brick red','Biuret: it turns violet','Sudan III: a red layer forms on top'],correct:0,
    steps:['Iodine is amber-brown on its own.','It turns blue-black where starch is present, like on a cut potato.','Benedict’s finds reducing sugars, Biuret finds protein and Sudan III finds fats.'],
    lab:{set:{reagent:'iodine'},act:'addAll',look:'Iodine is in every tube. Find the ones that turned blue-black, then compare with the water tube.'}},
  {id:'heat',kind:'test',lvl:'bio',
    q:'You add Benedict’s solution to glucose solution and nothing changes: the tube stays blue. What did you forget?',
    choices:['To heat it in a hot water bath','To add iodine as well','To cool it in ice','Nothing: glucose never reacts'],correct:0,
    steps:['Benedict’s only reacts with reducing sugars when it is heated.','In a hot water bath the color runs green, yellow, orange, then brick red as the amount of sugar goes up.','Without heat, every tube stays blue, sugar or not.'],
    lab:{set:{reagent:'benedict'},act:'addAll',look:'Every tube is still blue. Press <b>Heat in water bath (5 min)</b> and watch the sugary tubes change.'}},
  {id:'apple',kind:'real',lvl:'bio',
    q:'Apple juice is sweet but has no starch. You test it with Benedict’s (heated) and with iodine. What should you see?',
    choices:['Benedict’s turns orange or red; iodine stays amber','Benedict’s stays blue; iodine turns blue-black','Both stay the color of the reagent','Both turn positive'],correct:0,
    steps:['Fruit sugars like glucose and fructose are reducing sugars, so heated Benedict’s turns orange or red.','There is no starch, so iodine stays amber, the same as the water tube.','Growers use the opposite pattern on apples: unripe apples are full of starch and stain dark with iodine.'],
    lab:{set:{reagent:'benedict',tube:'7'},act:'add',look:'Benedict’s is in the apple juice tube. Press <b>Heat in water bath</b>, then switch the reagent to Iodine and add it.'}},
  {id:'control',kind:'test',lvl:'honors',
    q:'Why does every test include a tube of plain water?',
    choices:['It is the negative control: it shows what “no nutrient” looks like for each reagent','It makes the reagents work faster','It is the positive control','It has no purpose; it is extra'],correct:0,
    steps:['Reagents have their own color, like amber iodine or blue Benedict’s.','The water tube shows that color with nothing to react with.','A result only counts as positive if it looks different from the water tube.'],
    lab:{set:{reagent:'biuret'},act:'addAll',look:'Biuret is in every tube. Compare each tube with the water tube to decide which ones contain protein.'}},
  {id:'shade',kind:'ap',lvl:'ap',
    q:'Unknown X turns green with heated Benedict’s, and Unknown Y turns brick red. What can you conclude?',
    choices:['Y has more reducing sugar than X','X has more reducing sugar than Y','They have the same amount','Neither has sugar'],correct:0,
    steps:['Benedict’s is semi-quantitative: the color runs from blue (none) through green, yellow and orange to brick red as reducing sugar increases.','Green means a little sugar; brick red means a lot.','To turn this into a number you would compare against standards of known concentration.'],
    lab:{set:{reagent:'benedict'},act:'addAll',look:'Press <b>Heat in water bath</b>, then compare the shades of the sugary tubes.'}}
  ]},
protein:{
  apNote:'Protein structure and how its shape depends on its environment are AP Biology Unit 1 topics.',
  ap:[{title:'All released AP Biology exam questions',url:'https://apcentral.collegeboard.org/courses/ap-biology/exam/past-exam-questions',note:'Free-response questions by year, with scoring guidelines.'}],
  questions:[
  {id:'cooked',kind:'test',lvl:'bio',
    q:'An egg white turns solid and white in a hot pan. What is still the same about its proteins afterward?',
    choices:['The order of amino acids in each chain','The folded shape','How well they do their job','Nothing is the same'],correct:0,
    steps:['Heat shakes apart the weak bonds that hold a protein’s fold: hydrogen bonds, ionic bonds and hydrophobic clustering.','The strong peptide bonds between amino acids do not break, so the sequence stays the same.','The shape is lost, so the protein stops working. That is denaturation.'],
    lab:{set:{temp:90},look:'Watch % folded drop at 90 °C while the chain of beads stays linked.'}},
  {id:'core',kind:'test',lvl:'bio',
    q:'A protein folds in water. Where do its nonpolar (oily) amino acids end up?',
    choices:['Clustered in the middle, away from water','Spread across the outside, touching water','Scattered at random','Cut off the chain'],correct:0,
    steps:['Nonpolar side chains can’t form hydrogen bonds with water.','Water pushes them together, the way oil drops merge in salad dressing. This is the hydrophobic effect.','So a folded protein has an oily core and water-loving amino acids on its surface.'],
    lab:{act:'unfold',look:'The chain is stretched out. Watch the orange (nonpolar) beads gather in the middle as it folds.'}},
  {id:'ceviche',kind:'real',lvl:'honors',
    q:'In ceviche, lime juice (about pH 2) turns raw fish white and firm with no heat at all. Why?',
    choices:['The acid changes the charges on amino acids, breaking ionic bonds, so the proteins unfold','The acid cooks the fish by heating it','The acid breaks the peptide bonds into single amino acids','Lime juice adds new protein'],correct:0,
    steps:['At low pH, negative side chains like glutamate pick up H⁺ and lose their charge.','The ionic bonds (salt bridges) that held parts of the fold together break.','The proteins unfold, just as they do with heat. The sequence stays intact.'],
    lab:{set:{ph:2},look:'pH 2. Read <b>Ionic bonds</b> and <b>Folded</b>, then compare with pH 7.'}},
  {id:'sickle',kind:'test',lvl:'honors',
    q:'In sickle-cell disease, one negatively charged amino acid on hemoglobin’s surface is replaced by a nonpolar one. Why does that one change matter?',
    choices:['It leaves a sticky nonpolar patch on the surface, so hemoglobin molecules clump together','It breaks every peptide bond','It changes the protein into a carbohydrate','It doesn’t matter: one amino acid can’t change anything'],correct:0,
    steps:['The change is glutamate (charged) to valine (nonpolar) at one spot on the surface.','A nonpolar patch exposed to water sticks to nonpolar patches on other hemoglobin molecules.','The molecules stack into long fibers that bend red blood cells into a sickle shape.'],
    lab:{act:'sickle',look:'Read <b>Sticky nonpolar patch</b> and <b>Neighbor molecules</b> after the change.'}},
  {id:'levels',kind:'ap',lvl:'ap',
    q:'Which level of protein structure is held together by hydrogen bonds between the backbone C=O of one amino acid and the N–H of another, forming α-helices and β-sheets?',
    choices:['Secondary structure','Primary structure','Tertiary structure','Quaternary structure'],correct:0,
    steps:['Primary structure is the amino acid sequence, held by peptide bonds.','Secondary structure is local folding into helices and sheets, held by hydrogen bonds between backbone atoms.','Tertiary structure comes from side-chain interactions; quaternary structure is several chains together.']}
  ]}
,
cellexplorer:{
  questions:[
  {id:'plant',kind:'test',lvl:'bio',
    q:'Which structure do plant cells have that animal cells do not?',
    choices:['A cell wall','Ribosomes','A cell membrane','Mitochondria'],correct:0,
    steps:['Both plant and animal cells have a membrane, ribosomes and mitochondria.','Plant cells add a cellulose cell wall, a large central vacuole and chloroplasts.','The wall is why a plant cell in pure water firms up instead of bursting.'],
    lab:{set:{cell:'plant',part:'wall'},look:'The cell wall is highlighted. Switch Cell type to Animal and look for it.'}},
  {id:'bact',kind:'test',lvl:'bio',
    q:'Which statement about a bacterium is true?',
    choices:['It has ribosomes and a cell membrane, but no nucleus','It has a nucleus but no ribosomes','It has mitochondria and chloroplasts','It has no DNA'],correct:0,
    steps:['A bacterium is a prokaryote: its DNA sits in a region called the nucleoid, with no membrane around it.','It still needs ribosomes to make proteins and a membrane to control what enters.','It has no membrane-bound organelles, so no mitochondria or chloroplasts.'],
    lab:{set:{cell:'bacterium',part:'nucleoid'},look:'The nucleoid is highlighted. Notice there is no nuclear envelope around the DNA.'}},
  {id:'mito',kind:'real',lvl:'bio',
    q:'Heart muscle cells work nonstop and use a huge amount of ATP. Which organelle would you expect them to have a lot of?',
    choices:['Mitochondria','Chloroplasts','Cell walls','Vacuoles'],correct:0,
    steps:['Mitochondria carry out cellular respiration, which makes most of a cell’s ATP.','Cells that use lots of energy pack in more mitochondria. Heart muscle cells are among the richest.','Chloroplasts are only in plants and algae, and they make sugar, not ATP for the rest of the cell.'],
    lab:{set:{cell:'animal',part:'mito'},look:'Read the info panel for the mitochondrion.'}},
  {id:'route',kind:'test',lvl:'honors',
    q:'Insulin is made inside a pancreas cell and released outside it. In what order does it pass through these structures?',
    choices:['Ribosome on rough ER → vesicle → Golgi → vesicle → cell membrane','Golgi → rough ER → nucleus → cell membrane','Nucleus → mitochondrion → Golgi → cell membrane','Cell membrane → Golgi → rough ER → ribosome'],correct:0,
    steps:['A ribosome on the rough ER builds the protein, which folds inside the ER.','A vesicle carries it to the Golgi, which finishes and packages it.','A new vesicle fuses with the cell membrane and releases insulin outside: exocytosis.'],
    lab:{set:{cell:'animal',part:'golgi'},look:'Read about the Golgi, then press <b>Guided</b> to follow insulin the whole way.'}},
  {id:'membrane',kind:'ap',lvl:'ap',
    q:'In the cell membrane, which way do the parts of each phospholipid face?',
    choices:['Hydrophilic phosphate heads face the water inside and outside; hydrophobic tails face each other in the middle','Hydrophobic tails face the water; heads face the middle','All heads face outside the cell','Phospholipids lie flat in one single layer'],correct:0,
    steps:['Each phospholipid has a polar, water-loving head and two nonpolar fatty acid tails.','In water they form a bilayer: heads toward the watery cytoplasm and outside fluid, tails tucked in the middle.','That oily middle is why ions and large polar molecules need proteins to cross, while O₂ and CO₂ slip through.'],
    lab:{set:{cell:'animal',part:'membrane'},look:'Read about the cell membrane, then open the Membrane transport tool to see molecules cross it.'}}
  ]},
transport:{
  apNote:'Membrane transport, tonicity and water potential are AP Biology Unit 2 topics.',
  ap:[{title:'AP Biology equations and formulas sheet',url:'https://apcentral.collegeboard.org/media/pdf/ap-biology-equations-and-formulas-sheet.pdf',note:'Has Ψ = Ψp + Ψs and Ψs = −iCRT, with R = 0.0831 L·bar/mol·K.'},
      {title:'All released AP Biology exam questions',url:'https://apcentral.collegeboard.org/courses/ap-biology/exam/past-exam-questions',note:'Free-response questions by year, with scoring guidelines.'}],
  questions:[
  {id:'hyper',kind:'test',lvl:'bio',
    q:'A red blood cell is placed in a solution that is hypertonic to it. What happens?',
    choices:['Water leaves and the cell shrinks','Water enters and the cell swells','Salt enters and the cell swells','Nothing, because the membrane stops water'],correct:0,
    steps:['Hypertonic means the outside has more dissolved solute than the inside.','Water moves across the membrane toward the side with more solute, so it leaves the cell.','The cell shrinks and wrinkles (crenation). In 3% salt it shrinks to about 58% of its normal volume.'],
    lab:{set:{salt:3},look:'3% salt outside. Read <b>Cell volume</b> once it stops changing.'},verify:[['vol',57.5,.5]],wait:30},
  {id:'osmdir',kind:'test',lvl:'bio',
    q:'A cell has more dissolved salt inside than the water around it. The membrane lets water cross but not salt. Which way does water move?',
    choices:['Into the cell, toward the side with more solute','Out of the cell, toward the side with less solute','Salt moves out instead','Neither way'],correct:0,
    steps:['Salt can’t cross, so only water can even things out.','Water moves toward the side with more dissolved solute. That is osmosis.','So water enters and the cell swells. In 0.6% salt a red blood cell grows to about 128% of its normal volume and stops there.'],
    lab:{set:{salt:0.6},look:'0.6% salt outside, less than inside. Watch <b>Net water movement</b> and <b>Cell volume</b>.'},verify:[['vol',127.7,.5]],wait:30},
  {id:'versus',kind:'test',lvl:'bio',
    q:'Inside a cell there is 10 mM glucose; outside there is 1 mM. Glucose can cross through carriers. Which way does glucose move, and which way would water tend to move?',
    choices:['Glucose moves out; water tends to move in','Both move out','Both move in','Glucose moves in; water moves out'],correct:0,
    steps:['A solute diffuses from where it is more concentrated to where it is less. Glucose moves out, toward 1 mM.','Water does the opposite: it moves toward the side with more dissolved solute, which is inside.','Remember the pair: solutes go down their own gradient, and water goes toward more solute.'],
    lab:{set:{mol:'glucose',side:'in'},look:'Glucose starts at 10 mM inside. Watch <b>Inside the cell</b> fall as it leaves.'},verify:[['cin',2.18,.05]],wait:8},
  {id:'bilayer',kind:'test',lvl:'bio',
    q:'Which molecules can cross the cell membrane straight through the lipid bilayer, with no protein?',
    choices:['Small nonpolar molecules like O₂ and CO₂','Ions like Na⁺ and K⁺','Glucose','Proteins like insulin'],correct:0,
    steps:['The middle of the bilayer is made of oily fatty acid tails.','Small nonpolar molecules like O₂ and CO₂ dissolve in it and pass through. That is simple diffusion.','Ions and big polar molecules are blocked by the oily middle, so they need channels, carriers or pumps. Big proteins leave in vesicles.'],
    lab:{set:{mol:'o2'},look:'O₂ starts at 10 mM outside and 1 mM inside. After 2 s, read <b>Inside the cell</b> and <b>How it crosses</b>.'},verify:[['cin',6.71,.05]],wait:2},
  {id:'atp',kind:'test',lvl:'bio',
    q:'Which kind of transport uses ATP?',
    choices:['Simple diffusion','Facilitated diffusion','Osmosis','Active transport, like the Na⁺/K⁺ pump'],correct:3,
    steps:['Diffusion and osmosis are passive: molecules move down their gradient on their own.','Facilitated diffusion uses a protein, but it is still downhill, so it needs no ATP.','Active transport moves things against their gradient, from less to more. That costs energy: the Na⁺/K⁺ pump spends 1 ATP for every 3 Na⁺ it pushes out.'],
    lab:{set:{mol:'na'},look:'Na⁺ is 145 mM outside. Read <b>Uses ATP?</b> and watch <b>Inside the cell</b> stay near 12 mM.'},verify:[['cin',12.36,.1]],wait:30},
  {id:'iv',kind:'real',lvl:'bio',
    q:'A nurse grabs a bag of pure water instead of 0.9% saline and starts it into a patient’s vein. What happens to red blood cells near the needle?',
    choices:['They swell and burst','They shrink and wrinkle','Nothing: water is harmless','They turn into plant cells'],correct:0,
    steps:['Pure water has no solute, so it is hypotonic to the cells.','Water rushes in by osmosis. A red blood cell has no wall to push back.','It swells past about 150% of its volume and bursts (lysis). That is why IV fluids are matched to 0.9% salt.'],
    lab:{set:{salt:0},look:'Pure water outside. Watch the cell swell until it bursts.'}},
  {id:'carrier',kind:'test',lvl:'honors',
    q:'Glucose crosses a membrane through carrier proteins. Which statement is true?',
    choices:['It moves down its gradient with no ATP, and the carriers only let it through','Carriers always pump glucose into the cell using ATP','Carriers decide the direction, whatever the gradient','Glucose can cross the bilayer without the carriers'],correct:0,
    steps:['Carrier proteins give glucose a way across the oily bilayer. That is facilitated diffusion.','The gradient sets the direction: from more to less. No ATP is spent.','When the carriers are all busy, adding more glucose outside can’t speed it up much. The rate levels off.'],
    lab:{set:{mol:'glucose'},look:'Glucose starts at 10 mM outside. Watch the carriers and the <b>Inside the cell</b> reading.'},verify:[['cin',5.10,.05]],wait:5},
  {id:'plant',kind:'test',lvl:'honors',
    q:'A plant cell is moved from 0.9% salt into pure water. Why doesn’t it burst like a red blood cell?',
    choices:['Its cell wall pushes back (turgor pressure) until water stops entering','Plant cells don’t do osmosis','Its membrane has no aquaporins','It loses water instead'],correct:0,
    steps:['Water enters the plant cell by osmosis, just as it would a red blood cell.','The cell presses against its stiff cellulose wall, which pushes back with turgor pressure.','When that pressure balances the pull of the solutes, water stops entering. Here that happens at about 108% volume: firm, not burst.'],
    lab:{set:{cell:'plant',salt:0},look:'A plant cell in pure water. Read <b>Cell volume</b> and <b>Turgor pressure</b>.'},verify:[['vol',108.4,.3],['psiP',.67,.01]],wait:30},
  {id:'psi',kind:'ap',lvl:'ap',
    q:'A red blood cell (ψ ≈ −0.74 MPa) is moved into 1.5% NaCl (ψ = −1.26 MPa). Which way does water flow, and when does it stop?',
    choices:['Out of the cell, until ψ inside falls to −1.26 MPa','Into the cell, until it bursts','Out of the cell, until ψ inside reaches 0','No flow, because both are negative'],correct:0,
    steps:['Water flows from higher (less negative) ψ to lower ψ. −0.74 is higher than −1.26, so water leaves.','As water leaves, the solutes inside become more concentrated and ψ inside falls.','Flow stops when ψ inside equals ψ outside, −1.26 MPa. The cell is then about 75% of its normal volume.'],
    lab:{set:{salt:1.5},look:'Read <b>ψ inside</b> and <b>ψ outside</b> on the water potential graph until they meet.'},verify:[['psiIn',-1.257,.01],['psiOut',-1.257,.01],['vol',75.1,.5]],wait:30},
  {id:'psis',kind:'ap',lvl:'ap',
    q:'What is the solute potential of 0.15 M NaCl at 22 °C (295 K)? Use ψs = −iCRT with R = 0.00831 L·MPa/mol·K. Answer in MPa.',
    num:{ans:-0.74,tol:.02,unit:'MPa'},
    steps:['NaCl splits into Na⁺ and Cl⁻, so i = 2.','ψs = −2 × 0.15 × 0.00831 × 295 = −0.735 MPa.','That is about −0.74 MPa, close to normal saline (0.9% NaCl is about 0.154 M).']}
  ]},
potato:{
  questions:[
  {id:'gain',kind:'test',lvl:'bio',
    q:'A potato core gains mass after a day in a sugar solution. What does that tell you about the solution?',
    choices:['It was hypotonic to the potato cells: less dissolved solute than inside','It was hypertonic: more solute than inside','It was isotonic','Sugar moved into the core and added the mass'],correct:0,
    steps:['Mass changes mostly because water moves in or out by osmosis.','Water moves toward more solute. It moved into the core, so the cells had more solute than the solution.','So the solution was hypotonic to the cells.'],
    lab:{set:{bal:'1'},look:'Beaker 1 is pure water. Let the cores soak for 24 hours, then read <b>Mass change</b>.'}},
  {id:'pct',kind:'test',lvl:'honors',
    q:'A core goes from 2.50 g to 2.20 g. What is its percent change in mass?',
    num:{ans:-12,tol:.2,unit:'%'},
    steps:['Percent change = (final − initial) ÷ initial × 100.','= (2.20 − 2.50) ÷ 2.50 × 100 = −0.30 ÷ 2.50 × 100.','= −12%. The minus sign means the core lost mass, so the solution was hypertonic.']},
  {id:'iso',kind:'test',lvl:'honors',
    q:'Cores gain mass in 0.2 M sucrose and lose mass in 0.4 M sucrose. Where is the isotonic point?',
    choices:['Between 0.2 M and 0.4 M, where the graph crosses 0% change','Below 0.2 M','Above 0.4 M','At 0 M'],correct:0,
    steps:['Plot molarity (x) against percent mass change (y).','The line goes from positive at 0.2 M to negative at 0.4 M, so it crosses zero between them.','That crossing is the isotonic point, where the solution matches the cells. For this potato it is about 0.3 M.'],
    lab:{set:{range:'fine'},look:'The fine range runs 0.20 to 0.45 M. Weigh each core and read <b>Isotonic point</b>.'}},
  {id:'cucumber',kind:'real',lvl:'bio',
    q:'You sprinkle salt on cucumber slices, and after ten minutes beads of water appear on top. Why?',
    choices:['The salty surface is hypertonic, so water leaves the cucumber cells by osmosis','Salt melts into water','The cucumber is making new water','Salt dissolves the cell walls'],correct:0,
    steps:['The salt dissolves into a thin, very concentrated layer on the slice.','That layer has far more solute than the cucumber cells, so water moves out of the cells toward it.','The slices go limp for the same reason a potato core loses mass in strong sugar water.'],
    lab:{set:{bal:'6'},look:'Beaker 6 is 1.0 M sucrose. After the soak, read <b>Mass change</b>.'}},
  {id:'psi',kind:'ap',lvl:'ap',
    q:'Potato cores show no mass change in 0.25 M sucrose at 20 °C (293 K). What is the water potential of the potato cells? Use R = 0.0831 L·bar/mol·K. Answer in bar.',
    num:{ans:-6.09,tol:.05,unit:'bar'},
    steps:['At the isotonic point, the cells’ ψ equals the solution’s ψ. In an open beaker, ψp = 0, so ψ = ψs.','ψs = −iCRT = −1 × 0.25 × 0.0831 × 293.','= −6.09 bar. Sucrose does not split in water, so i = 1.']}
  ]},
wpotential:{
  apNote:'Water potential is on the AP Biology formula sheet and shows up in Unit 2 free-response questions.',
  ap:[{title:'AP Biology equations and formulas sheet',url:'https://apcentral.collegeboard.org/media/pdf/ap-biology-equations-and-formulas-sheet.pdf',note:'Has Ψ = Ψp + Ψs and Ψs = −iCRT.'}],
  questions:[
  {id:'psis',kind:'test',lvl:'bio',
    q:'What is Ψs of 0.20 M sucrose at 22 °C (295 K)? Use Ψs = −iCRT with R = 0.0831 L·bar/mol·K. Answer in bar.',
    num:{ans:-4.90,tol:.03,unit:'bar'},
    steps:['Sucrose does not break apart in water, so i = 1.','Ψs = −1 × 0.20 × 0.0831 × 295 = −4.90 bar.','The minus sign matters: dissolved solute always lowers water potential below 0.'],
    lab:{set:{conc:0.2},look:'Read <b>Ψ of the solution</b>.'},verify:[['psisol',-4.903,.01]]},
  {id:'dir',kind:'test',lvl:'bio',
    q:'A plant cell has Ψ = −7.0 bar. The solution around it has Ψ = −4.9 bar. Which way does water move?',
    choices:['Into the cell, toward the lower (more negative) Ψ','Out of the cell','Neither way','It depends on the size of the cell'],correct:0,
    steps:['Water always moves from higher Ψ to lower Ψ.','−4.9 bar is higher than −7.0 bar, so water moves from the solution into the cell.','As it enters, the wall pushes back (Ψp rises) until the cell’s Ψ matches −4.9 bar. Here Ψp ends near +2.1 bar.'],
    lab:{set:{conc:0.2},look:'Watch <b>Ψp of the cell</b> rise until <b>Ψ of the cell</b> equals <b>Ψ of the solution</b>.'},verify:[['psic',-4.903,.02],['psip',2.087,.02]],wait:60},
  {id:'salt',kind:'test',lvl:'honors',
    q:'Which solution has the same Ψs as 0.20 M sucrose at the same temperature?',
    choices:['0.10 M NaCl','0.20 M NaCl','0.40 M NaCl','0.10 M sucrose'],correct:0,
    steps:['NaCl splits into two particles, Na⁺ and Cl⁻, so i = 2.','0.10 M × 2 = 0.20 M of particles, the same as 0.20 M sucrose with i = 1.','Ψs depends on the number of dissolved particles, not the number of formula units.'],
    lab:{set:{conc:0.1,solute:'nacl'},look:'0.10 M NaCl. Compare <b>Ψ of the solution</b> with the 0.20 M sucrose value, −4.90 bar.'},verify:[['psisol',-4.903,.01]]},
  {id:'burn',kind:'real',lvl:'honors',
    q:'A gardener piles fertilizer right around a plant’s roots, and the leaves brown within days. What happened?',
    choices:['The soil water’s Ψ dropped below the roots’ Ψ, so water left the roots','The fertilizer added too much water','The roots took in too much fertilizer and grew too fast','Nothing to do with water'],correct:0,
    steps:['Fertilizer is salts. Dissolved in soil water, they make its Ψs very negative.','Once the soil’s Ψ is lower than the root cells’ Ψ, water flows out of the roots instead of in.','The plant loses water and wilts, just like a cell placed in strong sugar solution.'],
    lab:{set:{conc:0.5},look:'0.50 M outside. Watch the cell shrink and the membrane pull away from the wall.'},verify:[['vol',60,.5],['psip',0,.01]],wait:60},
  {id:'psip',kind:'ap',lvl:'ap',
    q:'At equilibrium in 0.20 M sucrose (Ψ = −4.90 bar), a cell’s Ψs is −6.99 bar. What is its pressure potential, Ψp? Answer in bar.',
    num:{ans:2.09,tol:.03,unit:'bar'},
    steps:['At equilibrium, Ψ of the cell = Ψ of the solution = −4.90 bar.','Ψ = Ψp + Ψs, so Ψp = Ψ − Ψs = −4.90 − (−6.99).','Ψp = +2.09 bar. The wall pushes back with this pressure.'],
    lab:{set:{conc:0.2},look:'Read <b>Ψs of the cell</b> and <b>Ψp of the cell</b> once flow stops.'},verify:[['psisc',-6.99,.02],['psip',2.087,.02]],wait:60}
  ]},
sav:{
  questions:[
  {id:'ratio',kind:'test',lvl:'bio',
    q:'What is the surface-area-to-volume ratio (SA:V) of a cube 2 cm on each side?',
    num:{ans:3,tol:.01,unit:'per cm'},
    steps:['Surface area = 6 faces × (2 cm × 2 cm) = 24 cm².','Volume = 2 × 2 × 2 = 8 cm³.','SA:V = 24 ÷ 8 = 3 per cm. A 1 cm cube has 6 per cm, twice as much.'],
    lab:{set:{sA:2},look:'Cube A is 2 cm. Read <b>Cube A SA:V</b>.'},verify:[['rA',3,.001]]},
  {id:'small',kind:'test',lvl:'bio',
    q:'Why are most cells tiny?',
    choices:['A small cell has more surface for its volume, so materials diffuse in and out fast enough','Small cells use more energy','Big cells can’t make DNA','Cells can’t grow, so they stay small'],correct:0,
    steps:['A cell takes in oxygen and food through its surface but uses them throughout its volume.','As a cell grows, volume grows faster than surface area, so SA:V falls.','Diffusion is also slow over long distances. After 10 minutes, acid has cleared the whole 1 cm cube but only about 70% of the 3 cm cube.'],
    lab:{look:'Watch the three cubes for 10 minutes and compare <b>reached</b> for each.'},verify:[['pA',100,.01],['pC',70.4,.1]],wait:10},
  {id:'time',kind:'test',lvl:'honors',
    q:'A 1 cm agar cube clears in 10 minutes. How long does a 2 cm cube take in the same vinegar?',
    choices:['20 minutes','40 minutes','80 minutes','10 minutes'],correct:1,
    steps:['Acid has to reach the center: 0.5 cm for the small cube, 1 cm for the big one.','Diffusion time grows with the square of the distance: twice as far takes 2² = 4 times as long.','4 × 10 = 40 minutes.'],
    lab:{set:{sA:2},look:'Cube A is now 2 cm. Read <b>Time to clear cube A</b>.'},verify:[['tA',40,.01]]},
  {id:'ice',kind:'real',lvl:'bio',
    q:'You have 100 g of ice as one big cube or as crushed ice. Which cools your drink faster, and why?',
    choices:['Crushed ice: many small pieces have far more surface touching the drink','The big cube, because it has more mass in one place','They cool at the same rate','The big cube, because it melts slower'],correct:0,
    steps:['Heat moves through surfaces, like materials moving into a cell.','Splitting the ice into small pieces keeps the same volume but adds a lot of surface area.','More surface means faster exchange. The same idea explains why cells stay small and lungs have millions of tiny air sacs.'],
    lab:{set:{sA:0.5,sB:1,sC:4},look:'Compare the SA:V readouts for the 0.5 cm and 4 cm cubes.'},verify:[['rA',12,.001],['rC',1.5,.001]]},
  {id:'slab',kind:'ap',lvl:'ap',
    q:'An agar block with the same volume as a 2 cm cube is flattened into a slab 4 cm × 4 cm × 0.5 cm. The 2 cm cube takes 40 minutes to clear. About how long does the slab take?',
    choices:['About 2.5 minutes','About 20 minutes','40 minutes, because the volume is the same','About 160 minutes'],correct:0,
    steps:['What matters is the distance to the center along the shortest direction: 0.25 cm for the slab, 1 cm for the cube.','Time grows with distance squared: (0.25 ÷ 1)² = 1/16.','40 ÷ 16 = 2.5 minutes. Flat and thin shapes, like red blood cells and leaves, exchange materials fast.'],
    lab:{set:{sA:2,shape:'slab'},look:'Cube A’s volume is now a flat slab. Read <b>Time to clear cube A</b>.'},verify:[['tA',2.5,.01]]}
  ]},
signaling:{
  apNote:'Cell communication and signal transduction are AP Biology Unit 4 topics.',
  ap:[{title:'All released AP Biology exam questions',url:'https://apcentral.collegeboard.org/courses/ap-biology/exam/past-exam-questions',note:'Free-response questions by year, with scoring guidelines.'}],
  questions:[
  {id:'outside',kind:'test',lvl:'bio',
    q:'Epinephrine never enters a liver cell. How does its message get inside?',
    choices:['It binds a receptor on the surface, which changes shape and starts a chain of relay molecules inside','It dissolves through the lipid bilayer','The cell swallows it in a vesicle','It doesn’t; the cell can’t respond'],correct:0,
    steps:['Epinephrine is charged and polar, so it can’t cross the oily middle of the membrane.','It fits a receptor on the outside. The receptor changes shape on the inside.','That shape change starts a relay (G protein, cAMP, kinases) that carries and multiplies the message.'],
    lab:{set:{epi:1},look:'Watch an epinephrine molecule bind the receptor while the relay lights up inside.'}},
  {id:'occ',kind:'test',lvl:'honors',
    q:'At 1 nM epinephrine, half the receptors hold hormone. At 10 nM, about what share do?',
    choices:['50%','About 91%','100%','500%'],correct:1,
    steps:['Binding follows bound share = C ÷ (C + 1 nM) for these receptors.','At 10 nM: 10 ÷ 11 = 0.909, about 91%.','Ten times the hormone does not mean ten times the binding. Once most receptors are full, more hormone adds little.'],
    lab:{set:{epi:10},look:'Read <b>Receptors with hormone</b> and <b>Glucose released</b>, then compare with 1 nM.'},verify:[['occ',90.9,.1]],wait:60},
  {id:'second',kind:'ap',lvl:'ap',
    q:'In the epinephrine pathway, which molecule is the second messenger that spreads the signal through the cytoplasm?',
    choices:['cAMP','Epinephrine','The receptor','Glycogen'],correct:0,
    steps:['Epinephrine is the first messenger: it stays outside.','The active G protein switches on adenylyl cyclase, which makes cAMP from ATP inside the cell.','cAMP is the second messenger: it diffuses through the cytoplasm and switches on protein kinase A.'],
    lab:{set:{epi:1},look:'Read <b>cAMP</b> with epinephrine at 1 nM, then set epinephrine to 0 and watch it fall.'},verify:[['camp',4.1,.05]],wait:60},
  {id:'inhaler',kind:'real',lvl:'bio',
    q:'An asthma inhaler (albuterol) binds the same kind of receptor as epinephrine, on airway muscle. Why does a tiny dose open the airways within minutes?',
    choices:['Each bound receptor sets off a relay that multiplies the signal thousands of times','The drug enters every cell and relaxes it directly','It dissolves the mucus','It replaces the muscle cells'],correct:0,
    steps:['The drug only has to bind receptors on the outside of the muscle cells.','Inside, one active receptor turns on many G proteins, each making many cAMP, each switching on kinases.','That cascade multiplies the message, so a small dose makes a big response quickly.'],
    lab:{set:{epi:1},look:'Read <b>Amplification</b>: glucose released per second for each bound hormone.'}},
  {id:'steroid',kind:'ap',lvl:'ap',
    q:'Testosterone is a steroid hormone; epinephrine is not. Where is each one’s receptor?',
    choices:['Testosterone’s is inside the cell; epinephrine’s is on the cell surface','Both are on the surface','Both are inside the nucleus','Testosterone’s is on the surface; epinephrine’s is inside'],correct:0,
    steps:['Steroids are lipids, made from cholesterol, so they pass through the lipid bilayer.','Their receptors are inside the cell, and the hormone-receptor pair often acts directly on genes.','Polar hormones like epinephrine and insulin can’t cross, so their receptors are on the surface and need a relay inside.']}
  ]},
phlife:{
  apNote:'How pH affects enzymes and proteins comes up in AP Biology Unit 3 (enzymes). Buffers are background chemistry for that.',
  ap:[{title:'All released AP Biology exam questions',url:'https://apcentral.collegeboard.org/courses/ap-biology/exam/past-exam-questions',note:'Free-response questions by year, with scoring guidelines.'}],
  questions:[
  {id:'tenx',kind:'test',lvl:'bio',
    q:'Five drops of acid take pure water from pH 7.0 to pH 3.3. About how many times more H⁺ is in the water now?',
    choices:['3.7 times','About 37 times','About 5,000 times','About 1,000,000 times'],correct:2,
    steps:['Each step on the pH scale is a factor of 10 in H⁺.','From pH 7.0 to pH 3.3 is 3.7 steps, so the factor is 10^3.7 ≈ 5,000. (4 full steps would be 10,000.)','A quarter of a milliliter of acid changes unbuffered water enormously. The common mistake is to subtract the pH values and stop at 3.7.'],
    lab:{set:{sol:'water'},act:'drop5',look:'Five drops of acid in pure water. Read the <b>pH meter</b> and <b>H⁺ compared with pure water</b>.'},verify:[['ph',3.30,.01]]},
  {id:'buffer',kind:'test',lvl:'bio',
    q:'What does a buffer do?',
    choices:['It takes up extra H⁺ or OH⁻, so the pH stays nearly the same','It makes a solution neutral, pH 7','It turns acids into bases','It speeds up enzymes'],correct:0,
    steps:['A buffer is a pair of chemicals. One member grabs H⁺; the other gives up H⁺ to cancel OH⁻.','So added acid or base gets taken up instead of floating free.','The phosphate buffer in your cells slips only from 7.20 to 7.16 after 5 drops of acid, while pure water drops to 3.30. A buffer holds its own pH; it doesn’t force pH 7.'],
    lab:{set:{sol:'cell'},act:'drop5',look:'Five drops of acid in phosphate buffer. Read the <b>pH meter</b> and the zoom.'},verify:[['ph',7.16,.01]]},
  {id:'enzyme',kind:'test',lvl:'bio',
    q:'Amylase from your saliva works best near pH 7. When you swallow, it reaches stomach acid at pH 2. What happens to it?',
    choices:['It stops working: the acid changes its shape','It works faster','It keeps working the same','It turns into pepsin'],correct:0,
    steps:['An enzyme’s shape depends on charges on its amino acids, and pH changes those charges.','At pH 2, far from its best pH, amylase loses the shape of its active site.','Its activity falls to about 0%. Starch digestion starts again in the small intestine, where pancreatic amylase works near neutral pH.'],
    lab:{set:{sol:'stomach',enz:'amylase'},look:'Amylase in stomach acid. Read <b>Enzyme activity</b>. Then switch the enzyme to Pepsin.'},verify:[['act',0,.5]]},
  {id:'tank',kind:'real',lvl:'bio',
    q:'Over a month, the water in a fish tank drifts from pH 7.0 down to pH 6.0 as fish waste breaks down. How has the H⁺ in the water changed?',
    choices:['It is 10 times higher','It is 1 unit higher, a tiny change','It is 10 times lower','It hasn’t changed'],correct:0,
    steps:['Lower pH means more H⁺.','One full pH step is a factor of 10, so pH 6 has 10 times the H⁺ of pH 7.','Fish keepers add a carbonate buffer, such as crushed coral or baking soda, so the water resists this drift.'],
    lab:{set:{sol:'water'},act:'drop1',look:'Just one drop takes unbuffered water from 7.00 to 4.00: 1,000 times more H⁺.'},verify:[['ph',4.00,.01]]},
  {id:'sprint',kind:'real',lvl:'honors',
    q:'During a hard sprint your muscles release acid into your blood, and you start breathing harder. How does breathing help hold blood pH near 7.4?',
    choices:['Blood’s bicarbonate turns the extra H⁺ into CO₂, and breathing removes the CO₂','Breathing brings in oxygen, which is a base','Breathing adds H⁺ to the blood','It doesn’t affect pH'],correct:0,
    steps:['HCO₃⁻ + H⁺ → H₂CO₃ → CO₂ + H₂O. The buffer turns the H⁺ into CO₂.','If the CO₂ stayed, the buffer pair would tip toward acid. In a sealed beaker, 5 drops lower blood buffer to 7.24.','Breathing carries the CO₂ away, so the pair stays balanced: the same 5 drops only take it to 7.39.'],
    lab:{set:{sol:'blood',lungs:true},act:'drop5',look:'Five drops of acid with breathing on. Read the <b>pH meter</b>, then turn breathing off and compare.'},verify:[['ph',7.39,.01]]},
  {id:'acidosis',kind:'test',lvl:'honors',
    q:'A patient’s blood pH is 7.25. What is this called, and about how much more H⁺ is in the blood than at 7.40?',
    choices:['Acidosis, about 1.4 times more H⁺','Alkalosis, about 1.4 times more H⁺','Acidosis, about 15 times more H⁺','Normal; 7.25 is in range'],correct:0,
    steps:['Blood’s safe range is 7.35 to 7.45. Below 7.35 is acidosis.','The difference is 0.15 pH units, and 10^0.15 = 1.41.','Even that small rise in H⁺ matters: the extra H⁺ changes charges on proteins, so enzymes and other proteins work less well.']},
  {id:'hh',kind:'ap',lvl:'ap',
    q:'Blood has 24 mM HCO₃⁻ and 1.2 mM dissolved CO₂, and the pKa is 6.1. Use pH = pKa + log([HCO₃⁻] ÷ [CO₂]). What is the pH?',
    num:{ans:7.40,tol:.01,unit:''},
    steps:['The ratio is 24 ÷ 1.2 = 20.','log(20) = 1.30.','pH = 6.1 + 1.30 = 7.40, normal blood.'],
    lab:{set:{sol:'blood'},look:'Blood buffer, nothing added yet. Read the <b>pH meter</b> and the <b>Henderson–Hasselbalch</b> readout.'},verify:[['ph',7.40,.01]]}
  ]}

});
